    "Count cache reads too": "快取讀取也計入",
    "Tokens are each call's uncached input, output and cache writes. The cost is an estimate at the Usage page's prices, not a bill. Windows are calendar ones in this computer's time (a week from Monday), or every N days or N hours from when the limit is set or reset. Requests from this computer without a key aren't limited.": "Token 計未命中快取的輸入、輸出和快取寫入。費用按用量頁價格估算，非帳單。週期按本機時間的自然日、週、月（每週從週一起），或從設定或重置額度時起每 N 天或每 N 小時。本機無金鑰的請求不受限額。",
