    "an open Claude Code session keeps the effort it started with — restart it to use this.": "已開啟的 Claude Code 會話仍用啟動時的推理強度，重開後生效。",
    "an open Claude Code session keeps the ultracode it started with — restart it to use this.": "已開啟的 Claude Code 會話仍用啟動時的 ultracode 設定，重開後生效。",
    "magpie's models join Codex's own; Codex stays signed in to ChatGPT, and while the Codex app blocks its account (out of allowance, no credits left) magpie is Codex's provider, so the app still sends": "預設。Codex 保持 ChatGPT 登入，magpie 的模型與 Codex 自帶模型並列；當 Codex 應用攔下該帳號（額度用盡且沒有剩餘積分）時，magpie 臨時作為 Codex 的供應商，讓 Codex 應用仍能傳送",
    "Always ChatGPT": "始終 ChatGPT",
    "as ChatGPT, and kept so while the Codex app blocks its account: magpie never becomes Codex's provider. The Codex app may then send nothing till the account has room; Codex CLI goes on through magpie": "同 ChatGPT，且 Codex 應用攔下該帳號時也不切換：magpie 不會成為 Codex 的供應商。此時 Codex 應用可能無法傳送，直到帳號恢復額度；Codex CLI 仍透過 magpie 繼續",
    "magpie is Codex's provider, with magpie's models only; the Codex app keeps its ChatGPT account (its chats, projects and Chrome control) while the account has room": "magpie 作為 Codex 的供應商，只列出 magpie 的模型；ChatGPT 帳號還有額度時，Codex 應用仍保留該帳號（聊天、專案和 Chrome 控制）",
