    "Lightweight mode": "輕量模式",
    "Prevent sleep": "防止休眠",
    "Keeps this computer awake while magpie runs tasks": "在 magpie 執行任務時，讓電腦保持喚醒狀態",
    "Keeps this computer and its screen awake while magpie runs tasks": "在 magpie 執行任務時，讓電腦和螢幕保持喚醒狀態",
    "Detect agents in WSL": "偵測 WSL 中的 Agent",
    "Looks in running WSL distros for agents to set up, their sessions and Claude Code; off, WSL is never asked anything and the agents found there are no longer shown": "在執行中的 WSL 發行版裡尋找可接入的 Agent、它們的工作階段和 Claude Code；關閉後不再向 WSL 詢問任何內容，之前在那裡找到的 Agent 也不再顯示",
    "Screen on too": "螢幕也常亮",
