    "Search first with": "優先使用",
    "MCP server": "MCP 伺服器",
    "Cursor, Claude Desktop and other agents can add this search as an MCP server (Streamable HTTP), with a web_search tool and a web_fetch tool that reads a page by its URL. From another computer, send a gateway key as Authorization: Bearer <key>.": "Cursor、Claude Desktop 等智慧體可以把這個搜尋新增為 MCP 伺服器（Streamable HTTP），提供 web_search 工具和依 URL 讀取網頁的 web_fetch 工具。從其他電腦存取時，請以 Authorization: Bearer <key> 傳送閘道金鑰。",
    "Ask {name}": "啟用 {name}",
    "Off: kept with its key, and never asked": "關閉：保留它和它的金鑰，但不再呼叫",
    "On: asked in its turn": "開啟：依順序輪到時呼叫",
    "Image recognition MCP server": "識圖 MCP 伺服器",
    "Agents can add image recognition as an MCP server (Streamable HTTP) with one analyze_image tool, which reads an image with the Image recognition model from a file path, a URL or a data URL. From another computer, send a gateway key as Authorization: Bearer <key> and the image as a URL or data URL.": "智慧體可以把識圖新增為 MCP 伺服器（Streamable HTTP），提供一個 analyze_image 工具：用識圖模型讀取檔案路徑、URL 或 data URL 中的圖片。從其他電腦存取時，請以 Authorization: Bearer <key> 傳送閘道金鑰，圖片以 URL 或 data URL 傳入。",
    "The other is asked when it fails": "失敗時再用另一種",
    "Models that search by themselves": "自帶聯網搜尋的模型",
