    "magpie's": "magpie 代搜",
    "When provider search is off, only configured Search APIs are used, for every model. Without a Search API, magpie does not add a search tool.": "關閉供應商代搜後，所有模型都只使用已設定的搜尋 API；未設定時，Magpie 不新增搜尋工具。",
