    "When provider search is off, only configured Search APIs are used. Without a Search API, magpie does not add a search tool. Providers' native web search is unchanged.": "關閉供應商代搜後，僅使用已設定的搜尋 API；未設定時，Magpie 不新增搜尋工具。供應商內建的聯網搜尋不受影響。",
    "Provider search is off; only these APIs are used": "已關閉供應商代搜，僅使用這些 API",
    "Searches for other models": "代搜供應商",
    "When a model can't search the web directly, the selected provider searches for it and returns the results. Searches may use the service's quota or incur charges; if the provider magpie picks fails, it tries other available sources, and a provider you select here gives way to the ones you add after it, in their order, then, when it can't search at all (out of quota or rate-limited), to other available sources, then to your Search APIs.": "當模型無法直接聯網搜尋時，由所選供應商代為搜尋並返回結果。代搜可能消耗所用服務的額度或產生費用；magpie 自動選擇的供應商失敗時會嘗試其他可用來源，在此手動選中的供應商失敗時會依序換成你在它後面新增的供應商；若它完全搜不了（額度用完或被限流），再嘗試其他可用來源，最後改用你設定的搜尋 API。",
    "{who} didn't search {when}: {why}. {next} searched in its place.": "{who} {when}沒能搜尋：{why}。已由 {next} 代為搜尋。",
    "{who} didn't search {when}: {why}. The ones after it didn't search either; add another provider after it, or a Search API.": "{who} {when}沒能搜尋：{why}。排在它後面的供應商也都沒能搜尋；可在它後面再新增一個供應商，或新增搜尋 API。",
    "If it fails": "失敗時依序換用",
    "These providers search in its place, in this order, when the one above fails; no other provider does.": "上面的供應商搜尋失敗時，依此順序由這些供應商代為搜尋；不會換用其他供應商。",
    "{who} didn't search {when}: {why}. No other provider searched in its place; pick Automatic or another provider, or add a Search API.": "{who} {when}沒能搜尋：{why}。沒有換用其他供應商代搜；可改選「自動」或其他供應商，或新增搜尋 API。",
    "it answered without searching the web, so its account or plan may not offer web search": "它沒有聯網搜尋就直接回答了，它的帳號或方案可能不支援聯網搜尋",
    "no provider that searches": "沒有能搜尋的供應商",
    "{model}, its small model": "{model}（它的小模型）",
    "its web search": "它自帶的聯網搜尋",
    "A Kimi Code plan ({names}) searches for its own models first, with its web search; for other models only when named here": "Kimi Code 套餐（{names}）的模型優先用套餐自帶的聯網搜尋；其他模型僅在此處選中時使用",
    "{names} search for their own models first, with Gemini's Google Search": "{names} 的模型優先用 Gemini 自帶的 Google 搜尋",
    "it is no longer in magpie": "它已不在 magpie 裡",
    "it is turned off": "它已關閉",
