    "{who} isn't used: {why}, so magpie picks one": "沒有用 {who}：{why}，改由 magpie 自動選擇",
    "These relays must be selected manually and are not used for automatic selection or fallback: {names}.": "以下中轉服務需手動指定，不參與自動選擇或自動回退：{names}。",
    "These providers can't be selected to search for other models with the current configuration: {names}. Their models can still get search results through other available search providers or configured search APIs.": "以下供應商在目前設定下不可選為代搜供應商：{names}。它們的模型仍可透過其他可用的代搜供應商或已設定的搜尋 API 取得搜尋結果。",
