    "Sign {name} out of magpie?": "在 magpie 裡退出 {name}？",
    "magpie signs out the accounts it keeps for {name} and forgets them; adding {name} again signs in afresh. The account itself is left as it is.": "退出並移除為 {name} 儲存的帳號；再次新增 {name} 需重新登入。帳號本身不受影響。",
    "magpie signs out the accounts it keeps for {name}; adding it again signs in afresh": "退出為 {name} 儲存的帳號；再次新增需重新登入",
    "{name} signed out": "已退出 {name}",
    "{agent} is signed in to {user} now: sign it in to another of its accounts first (Use on that account), then remove this one": "{agent} 目前登入的是 {user}：請先在另一個帳號上點「使用」把 {agent} 切過去，再移除這個帳號",
    "{agent} is signed in to {user}, the only account in magpie it can be signed in to, and magpie doesn't sign it out: add another account first, or sign out in {agent} itself, then remove this one": "{agent} 目前登入的是 {user}，這是 magpie 裡它唯一能登入的帳號，magpie 不會把它登出：請先新增另一個帳號，或在 {agent} 裡自行登出，再移除這個帳號",
    "Signs Codex out of this account, as codex logout does": "讓 Codex 退出這個帳號，與 codex logout 相同",
    "{agent} is signed in to another of its accounts, and magpie forgets this one; the account itself is untouched": "{agent} 會先登入到它的另一個帳號，magpie 再忘掉這個帳號；帳號本身不受影響",
    "Codex itself is signed out too, as codex logout does.": "Codex 本身也會退出登入，與 codex logout 相同。",
