    "{agent} is signed out, as codex logout does, and magpie forgets the account. Sign in again to use it; an open {agent} may need quitting and opening again. The account itself is left as it is.": "{agent} 會退出登入（與 codex logout 相同），magpie 也不再儲存這個帳號。要再用需重新登入；已開啟的 {agent} 可能要退出後重新開啟。帳號本身不受影響。",
