    "turned off": "已停用",
    "resting": "休息中",
    "The first is tried first; the other {n} are added to its accounts": "第一個優先使用，其餘 {n} 個加為它的帳號",
    "Add many keys at once, one a line or separated by commas": "一次新增多個金鑰，每行一個或用逗號分隔",
    "Add another key": "新增另一個金鑰",
    "Name (optional), e.g. Team": "名稱（可選），例如 團隊",
    "Name, e.g. Personal or Team": "名稱，例如 個人 或 團隊",
    "Name this account": "為此帳號命名",
    "{user} · click to rename": "{user} · 點擊改名",
    "The same seat as the key plan {name}, shown once, on this account's card": "與 Key 方案「{name}」是同一個席位，只在此帳號的卡片上顯示一次",
    "Rename": "重新命名",
    "Renamed {name} to {new}": "已將 {name} 重新命名為 {new}",
    "Key removed": "已移除金鑰",
    "Key added — it takes over when the ones before it run out": "已新增金鑰，前面的金鑰用完時由它接上",
    "Use": "使用",
    "Add another {name} account": "新增另一個 {name} 帳號",
    "WorkBuddy AI (international)": "WorkBuddy 國際版 (WorkBuddy AI)",
    "Qoder (international)": "Qoder 國際版 (qoder.com)",
    "Sign in with ChatGPT: your plan on OpenAI's own API, with your agent's own instructions rather than Codex's.": "用 ChatGPT 登入（Sign in with ChatGPT）：透過 OpenAI 官方 API 使用你的套餐，用的是你 agent 自己的指令，而不是 Codex 的。",
    "For accounts on qoder.com, the international site.": "適用於 qoder.com（國際站）的帳號。",
    "For accounts on qoder.cn: signed in with an Alibaba Cloud account or a phone number.": "適用於 qoder.cn 的帳號：阿里雲帳號 / 手機號登入。",
    "Sign in to another {name} account": "換一個 {name} 帳號登入",
    "{agent} keeps one account; the gateway runs it for every request. Signing in to another replaces it.": "{agent} 只儲存一個帳號，閘道的所有請求都用它。登入其他帳號會替換它。",
    "{name} subscription": "{name} 訂閱",
    "Finish signing in to {name} in your browser": "請在瀏覽器中完成 {name} 登入",
    "{name} accounts can be suspended": "{name} 帳號可能被封禁",
    "Google may suspend an Antigravity account it sees used outside Antigravity. Use one you can afford to lose.": "Google 可能封禁在 Antigravity 之外使用的 Antigravity 帳號。請用丟了也不心疼的帳號。",
    "Sign in anyway": "仍然登入",
    "Where is your {name} account?": "你的 {name} 帳號在哪個站點？",
    "Sign in where your GLM Coding Plan was bought, a team's plan too: z.ai, or bigmodel.cn for 智谱.": "在購買 GLM Coding Plan 的站點登入，團隊套餐也一樣：z.ai，或智譜的 bigmodel.cn。",
    "BigModel (智谱)": "智譜 BigModel",
    "Installing {cli}…": "正在安裝 {cli}…",
    "{name} is used through its own CLI, which isn't on this computer yet. magpie is installing it with the official installer; the sign-in page opens as soon as it's done.": "{name} 需透過自身 CLI 使用，本機尚未安裝。正在用官方安裝指令碼安裝，完成後立即開啟登入頁。",
    "magpie opened the sign-in page. The account shows up here as soon as you're done.": "已開啟登入頁，完成後帳號會出現在這裡。",
    "Open again": "重新開啟",
    "Sign-in pages": "登入頁",
    "Open sign-in pages in the browser": "在瀏覽器中開啟登入頁",
    "Adding an account opens its sign-in page in your default browser. Off, magpie only shows the link, to copy into the browser you sign in with": "新增帳號時會在預設瀏覽器中開啟登入頁。關閉後，magpie 只顯示連結，複製到你用來登入的瀏覽器裡開啟",
    "magpie didn't open the sign-in page, as set in Settings. Copy the link below into the browser you sign in with.": "magpie 依設定沒有開啟登入頁。把下面的連結複製到你用來登入的瀏覽器裡。",
    "Other ways to sign in…": "其他登入方式…",
    "ZCode app's sign-in": "使用 ZCode 應用已登入的帳號",
    "GLM Coding Plan API key": "GLM Coding Plan API Key",
    "Stop waiting for this sign-in": "不再等待這次登入",
    "Copy link": "複製連結",
    "Sign-in link": "登入連結",
    "magpie couldn't open your browser: {error}. Open the sign-in link below in a browser yourself.": "magpie 無法開啟瀏覽器：{error}。請自行在瀏覽器中開啟下方的登入連結。",
    "Your browser blocked the sign-in page from opening. Open it with Open again below, or copy the link into a browser.": "瀏覽器擋下了登入頁面，沒讓它開啟。請點下方的「重新開啟」，或把連結複製到瀏覽器中開啟。",
    "Proxy: {proxy}": "代理：{proxy}",
    "The sign-in goes through this proxy, as the account's requests will. One picked here is kept as the account's.": "登入經由這個代理，與這個帳號之後的請求相同。在這裡選的代理會儲存為這個帳號的代理。",
    "Sign in through": "登入經由",
    "Through no proxy": "不經過代理",
    "{name}'s proxy": "{name} 的代理",
    "{user}'s proxy": "{user} 的代理",
    "Custom…": "自訂…",
    "http://, https:// or socks5://": "http://、https:// 或 socks5://",
    "Sign in through it": "經由它登入",
    "Account in use": "正在使用的帳號",
    "Open it in another browser or profile: copy it there": "要用其他瀏覽器或瀏覽器設定登入，複製此連結到那裡開啟",
    "If the page the browser ends on won't load (magpie runs on a server or in Docker), copy its whole address and paste it here.": "若瀏覽器最終停在打不開的頁面（magpie 執行在伺服器或 Docker 中），請複製其完整位址貼上到這裡。",
    "Windows keeps port {port}, where the sign-in comes back, for Hyper-V, WSL or Docker, so the page the browser ends on won't load. Copy its whole address and paste it here.": "Windows 為 Hyper-V、WSL 或 Docker 保留了登入回呼的連接埠 {port}，瀏覽器最終停在的頁面將無法開啟。請複製其完整位址貼上到這裡。",
    "Another program has port {port}, where the sign-in comes back, so the page the browser ends on won't finish the sign-in. Copy its whole address and paste it here.": "登入回呼的連接埠 {port} 被其他程式佔用，瀏覽器最終停在的頁面無法完成登入。請複製其完整位址貼上到這裡。",
    "Callback URL": "回呼 URL",
    "If the page can't reach magpie (it runs on a server or in Docker), make an API key on {name}'s keys page and paste it here.": "若頁面連不上 magpie（執行在伺服器或 Docker 中），請在 {name} 的金鑰頁建立 API 金鑰並貼上到這裡。",
    "Open the keys page": "開啟金鑰頁面",
    "Use an API key instead": "改用 API 金鑰",
    "If the page can't reach magpie (it runs on a server or in Docker)": "頁面連不上 magpie 時（執行在伺服器或 Docker 中）",
