    "1 provider to bring over": "有 1 個供應商可匯入",
    "{n} providers to bring over": "有 {n} 個供應商可匯入",
    "magpie opened ChatGPT's device page. Enter this code there; the account shows up here as soon as you're done.": "已開啟 ChatGPT 裝置登入頁，請在其中輸入下方驗證碼；完成後帳號會出現在這裡。",
    "Sign in with a code instead": "改用驗證碼登入",
