    "For magpie on a server or in Docker: enter a code on ChatGPT's page, with no address to copy back": "適合 magpie 執行在伺服器或 Docker 中時：在 ChatGPT 頁面輸入驗證碼，無需複製回呼位址",
    "magpie opened GitHub's device page. Enter this code there; the account shows up here as soon as you're done.": "已開啟 GitHub 裝置登入頁，請在其中輸入下方驗證碼；完成後帳號會出現在這裡。",
