    "magpie has {name} already": "magpie 裡已有 {name}",
    "{name} is a subscription in magpie; this one comes in beside it as a provider of its own": "{name} 是 magpie 裡的訂閱；這一項會作為單獨的供應商加在它旁邊",
    "Add as a new provider": "作為新的供應商",
    "Keep both": "兩個都保留",
    "Replace it": "替換原有的",
