    "This computer's {parts} become the ones on the server, as your other computers last synced them. Whatever was changed here since is replaced.": "本機的{parts}將換成伺服器上的（其他電腦最後同步的版本），本機之後的改動會被替換。",
    "What is here now is sealed into the sync folder first, and Undo puts it back.": "目前設定會先加密備份到 sync 資料夾，可點「復原」換回。",
