    "What another computer wrote into that file and has nowhere else is lost. If one of them synced it last, Sync now there may rebuild it instead.": "另一台電腦寫進那個檔案、別處沒有的內容會遺失。如果是其他某台電腦最後同步的，在那台電腦上點「立即同步」可能可以直接修復。",
