    "As of {when} — couldn't be read just now": "截至 {when}，暫時無法取得最新額度",
    "As of {when} — not refreshed this time": "截至 {when}，本次未主動重新整理",
    "A cached window has expired; current allowance is unknown": "快取中有時段已過期，其目前額度未知",
    "As of {when}": "截至 {when}",
