    "Reset time passed {when}": "重置時間已過 {when}",
    "Hide allowances": "收起額度",
    "Show allowances": "展開額度",
    "Signed out — choose Sign in again on this account under Providers": "已登出 — 請在「供應商」中此帳號上選擇「重新登入」",
    "Needs a Google Cloud project — hover for how": "需要指定 Google Cloud 專案，懸停檢視方法",
    "Google no longer serves personal accounts to Gemini CLI — hover for more": "Google 已停止向個人帳號提供 Gemini CLI，懸停檢視詳情",
    "Google has suspended this account — hover for details": "此帳號已被 Google 停用，懸停檢視詳情",
    "This key has no limit — add the account's access token in the provider's settings to see its balance": "此 key 未設額度，在供應商設定中填入帳戶存取權杖即可檢視餘額",
    "ZCode: no GLM Coding Plan, and no free Start Plan — subscribe to a GLM Coding Plan to use this account": "ZCode：沒有 GLM Coding Plan，也沒有免費的體驗套餐 — 請訂閱 GLM Coding Plan 後使用該帳號",
    "AiHubMix didn't take the access token — paste a new one in the provider's settings": "AiHubMix 不認這個存取權杖，請在供應商設定裡重新填入",
    "Account balance": "帳戶餘額",
    "Step Plan allowances": "Step Plan 額度",
    "Team org ID": "團隊組織 ID",
    "Team project ID": "團隊專案 ID",
    "optional · only for a team plan": "可選 · 僅團隊套餐需要",
    "Only for a key on a team's GLM Coding Plan: both are in {p}'s console, under the team's organization and project. With them the Usage page shows the team's 5-hour and weekly windows.": "僅團隊 GLM Coding Plan 的 Key 需要：兩者見 {p} 控制台的團隊組織與專案。填寫後用量頁顯示團隊的 5 小時與每週額度。",
    "Team plan: give both the organization ID and the project ID": "團隊套餐：請同時填寫組織 ID 和專案 ID",
    "AccessKey ID": "AccessKey ID",
    "Secret Access Key": "Secret Access Key",
    "The plan's 5-hour, weekly and monthly windows are told only to the account's access key (Volcengine console → API Access Keys), not to the plan's API key. Give it here for the Usage page to show them; it is used for nothing else.": "套餐的 5 小時、每週和每月額度只對帳號的存取金鑰開放（火山引擎控制台 → API 存取金鑰），套餐的 API Key 查不到。填在這裡，用量頁就會顯示它們；僅用於查詢額度。",
    "SecretId": "SecretId",
    "SecretKey": "SecretKey",
    "Token Plan Enterprise's usage is told only to the Tencent Cloud account's API key (console → Access management → API keys), not to the plan's API key. Give its SecretId and SecretKey here for the Usage page to show it; a sub-user's key that may read TokenHub is enough. It is used for nothing else.": "Token Plan 企業版的用量只對騰訊雲帳號的 API 金鑰開放（主控台 → 存取管理 → API 金鑰管理），套餐的 API Key 查不到。在這裡填入它的 SecretId 和 SecretKey，用量頁就會顯示；有 TokenHub 讀取權限的子使用者金鑰即可。僅用於查詢用量。",
    "This plan's usage needs the account's AccessKey ID and Secret — give them in the provider's settings": "此方案的用量需要帳號的 AccessKey ID 和 Secret 才能讀取，請在服務商設定中填寫",
    "Open settings": "開啟設定",
    "This plan's usage needs the account's SecretId and SecretKey — give them in the provider's settings": "此方案的用量需要帳號的 SecretId 和 SecretKey 才能讀取，請在服務商設定中填寫",
    "Give the access key's Secret too": "請同時填寫存取金鑰的 Secret",
    "A key tells only the balance. The Step Plan's 5-hour, weekly and credit windows are told only to a StepFun sign-in: bring yours here once and magpie keeps it (for 30 days), used for nothing else.": "API Key 只能查餘額。Step Plan 的 5 小時、每週和積分額度僅對 StepFun 網頁登入開放：匯入一次登入，magpie 儲存 30 天，僅用於查詢額度。",
    "Signed in · the Usage page shows the Step Plan": "已登入 · 用量頁會顯示 Step Plan 額度",
    "Sign out": "退出登入",
    "Sign in to StepFun in your browser ↗": "在瀏覽器中登入 StepFun ↗",
    "Drag ": "把 ",
    " to the bookmarks bar (or ": " 拖到書籤列（或",
    "copy it": "複製它",
    " as a bookmark's URL), then click it on the signed-in page": "作為新書籤的網址），然後在已登入的 StepFun 頁面上點它",
    "paste what it copied": "貼上它複製的內容",
    "Bookmarklet": "書籤小工具",
    "Signed in to StepFun": "已登入 StepFun",
    "saved · paste a new one to replace it": "已儲存 · 貼上新的即可替換",
    "optional · the account's system access token": "可選 · 帳戶的系統存取權杖",
    "What the Balance URL is asked with in place of the key, when it wants the account's own token: a new-api relay's System Access Token, or a sub2api panel's login token (a JWT, sent as a Bearer); it is used for nothing else.": "餘額介面需要帳戶自己的令牌時，用它代替 Key 去請求：new-api 中轉站填「系統存取權杖」，sub2api 面板填登入令牌（JWT，會以 Bearer 傳送）；不作他用。",
    "…/api/usage/token takes the API key, not this token: for the account's balance, new-api uses /api/user/self; sub2api uses /api/v1/user/profile.": "…/api/usage/token 只認 API Key，不認這個令牌：查帳戶餘額時，new-api 使用 /api/user/self，sub2api 使用 /api/v1/user/profile。",
    "…/v1/usage takes the API key, not this token: for the account's balance, a sub2api panel uses /api/v1/user/profile.": "…/v1/usage 只認 API Key，不認這個令牌：查帳戶餘額時，sub2api 面板使用 /api/v1/user/profile。",
    "The Balance URL …/v1/usage takes the API key, not the login token — set it to …/api/v1/user/profile in the provider's settings": "餘額查詢位址 …/v1/usage 只認 API Key，不認登入令牌，請在供應商設定裡改為 …/api/v1/user/profile",
    "The token needs a Balance URL: a new-api relay uses /api/user/self; a sub2api panel uses /api/v1/user/profile to read the account's balance.": "令牌還需要一個餘額查詢位址：new-api 中轉站用 /api/user/self 憑令牌查帳戶餘額；sub2api 面板用 /api/v1/user/profile。",
    "Use {url}": "改用 {url}",
    "A new-api relay also wants the header New-Api-User = your user ID (shown in the site's personal settings): add it under Headers.": "new-api 中轉站還需請求頭 New-Api-User = 你的使用者 ID（見站點個人設定），請在「請求頭」中新增。",
    "The Balance URL …/api/usage/token takes the API key, not the access token — set it to …/api/user/self in the provider's settings": "餘額查詢位址 …/api/usage/token 只認 API Key，不認存取權杖，請在供應商設定裡改為 …/api/user/self",
    "Add the header New-Api-User = your user ID (shown in the site's personal settings) to the provider's Headers": "請在供應商的「請求頭」中新增 New-Api-User = 你的使用者 ID（見站點個人設定）",
    "Check balance": "查詢餘額",
    "Ask the Balance URL now, as the form has it": "按表單目前的填寫立即查詢一次餘額",
    "No Balance URL to ask": "沒有可查詢的餘額位址",
    "A key tells only what is left on itself. For the whole account's balance on the Usage page, generate a System Access Token in {p}'s settings and paste it here; it is used for nothing else.": "API key 只能查到自身剩餘額度。要在用量頁顯示整個帳戶餘額，請在 {p} 的設定中生成系統存取權杖並貼上到這裡，不作他用。",
