    "Network and sharing": "網路與共享",
    "Model ids without the provider": "不帶供應商的模型 ID",
    "The gateway’s model list also names each model by its own id, as gpt-5.6-sol beside codex/gpt-5.6-sol, for apps moved from another proxy. One that several providers serve goes to them in the Providers order": "閘道的模型列表還會以模型自己的 ID 列出每個模型，如 codex/gpt-5.6-sol 旁的 gpt-5.6-sol，供從其他代理遷來的應用使用。多個供應商都提供的模型，按「供應商」中的順序發往它們",
    "Busy models last": "繁忙的模型靠後",
    "A model its plugin says is busier than this goes after the others a request could go to, as its vendor makes it wait. One with no load reported in the last 5 minutes keeps its place": "外掛回報負載高於此值的模型，排在請求可去的其他模型之後，因為它的供應商會讓請求排隊等待。最近 5 分鐘內沒有回報負載的模型保持原位",
    "Over {n}%": "高於 {n}%",
    "A load is in percent, as the plugin reports it: 100 is all its vendor serves at once, and past 100 requests queue (200 is twice that). Type 1 to 9999": "負載以百分比計，由外掛回報：100 表示供應商同時能處理的全部量，超過 100 表示請求在排隊（200 即兩倍）。輸入 1 到 9999",
    "Type a whole number from 1 to 9999": "請輸入 1 到 9999 之間的整數",
    "{n}% busy now, as its plugin says": "外掛回報目前負載 {n}%",
