    "Update hidden until the next version; Settings still has it": "已隱藏更新按鈕，下一個版本釋出時再顯示；設定裡仍可更新",
    "The `magpie` command is a copy": "終端機裡的 `magpie` 命令是一份複製",
    "{file} was damaged (the computer likely stopped mid-write), so magpie restored it from its backup of {time}. A change made after that may be missing; the damaged file is kept beside it.": "{file} 已損壞（多半是電腦在寫入途中停機），magpie 已從 {time} 的備份還原。之後的變更可能缺失；損壞的檔案保留在旁邊。",
    "{file} was damaged (the computer likely stopped mid-write), so magpie restored it from its backup. A change made after that may be missing; the damaged file is kept beside it.": "{file} 已損壞（多半是電腦在寫入途中停機），magpie 已從備份還原。之後的變更可能缺失；損壞的檔案保留在旁邊。",
    "The `magpie` command at {path} is a copied file, not the installer's link to the app: it won't follow the app's updates, and an old copy can break what a new one fixed. Re-run the installer, or link it by hand.": "`magpie` 命令（{path}）是複製的檔案，不是安裝指令碼建立的應用連結：不會隨應用更新，舊複製可能使新版的修復失效。請重新執行安裝指令碼，或手動建立連結。",
    "Update button": "更新按鈕",
    "Shows in the header when a newer magpie is out": "magpie 有新版本時顯示在頂欄",
    "Hidden for {v} until a newer version is out": "{v} 已隱藏，更新的版本釋出時再顯示",
