    "One version a week, out for three days first, and urgent fixes at once. What's new lists every change since yours": "每週一個版本，發布滿三天後才推送；緊急修正立即推送。「更新內容」會列出你目前版本以來的全部變更",
    "While automatic updates are on": "自動更新開啟時生效",
    "Restart automatically": "自動重新啟動更新",
    "Download updates automatically": "自動下載更新",
    "Off: a newer version is only shown, with its size; it downloads when you click Download update. For metered networks and proxies billed by traffic": "關閉：發現新版本時只顯示版本和大小，點擊「下載更新」後才下載。適合按流量計費的網路或代理",
    "Downloads a newer version as soon as it is found. Turn off on a metered network or a proxy billed by traffic": "發現新版本後立即下載。使用按流量計費的網路或代理時可以關閉",
    "Download update": "下載更新",
    "Click to download and restart": "點擊下載並重新啟動更新",
    "Once an update is downloaded, restarts into it without cutting off an agent's request": "新版本下載完成後自動重新啟動到新版本，不會中斷 Agent 的請求",
