    "restarts once the Claude subscription's replies have finished": "Claude 訂閱的回覆結束後自動重啟",
    "magpie restarts to update to {v} once the replies through a Claude subscription have finished: {busy}. Other requests carry on across the restart. Click to restart now.": "Claude 訂閱的回覆結束後，magpie 將重啟以更新到 {v}：{busy}。其他請求不受重啟影響。點選立即重啟。",
    "Restart now": "立即重啟",
