    "{v} didn't start on this computer: Windows' Smart App Control (or another app control policy) blocked the new version, which isn't signed. magpie stays on {cur}. Download it and run it yourself, or turn Smart App Control off and check again": "{v} 沒能在這臺電腦上啟動：Windows 的「智慧應用控制」（或其他應用控制策略）攔下了未簽名的新版本，magpie 仍是 {cur}。可以下載新版本自己執行，或關掉智慧應用控制後再檢查更新",
