    "Click to open the download page.": "點選開啟下載頁面。",
    "macOS is running magpie from a temporary copy, so it can't update itself; move magpie to Applications and open it from there.": "macOS 正從臨時副本執行 magpie，無法自動更新；請將 magpie 移到「應用程式」資料夾後從那裡開啟。",
    "magpie is running from its disk image, so it can't update itself; drag it to Applications and open it from there.": "magpie 正從磁碟映像執行，無法自動更新；請將它拖到「應用程式」資料夾後從那裡開啟。",
    "magpie can't write to the folder it runs from ({dir}), so it can't update itself; move it to a folder you can write to and open it from there.": "magpie 無法寫入它所在的資料夾（{dir}），所以無法自動更新；請把它移到你有寫入權限的資料夾，再從那裡開啟。",
    "{manager} installed magpie ({pkg}), so {manager} updates it, not magpie: {cmd}": "{manager} 安裝了 magpie（{pkg}），所以由 {manager} 更新它，而不是 magpie 自己：{cmd}",
    "{manager} installed magpie, so {manager} updates it, not magpie.": "由 {manager} 安裝的 magpie 由 {manager} 更新，而不是 magpie 自己。",
    "magpie runs in a container, so it can't update itself; pull the new image (docker pull ghcr.io/yetone/magpie:latest) and recreate the container.": "magpie 在容器中執行，無法自動更新；請拉取新映像（docker pull ghcr.io/yetone/magpie:latest）並重新建立容器。",
    "Config folder": "設定目錄",
    "Log": "日誌",
    "What magpie has logged, to send with a bug report": "magpie 記下的日誌，回報問題時可附上",
