    "Updates are downloaded through this mirror, each checked against usemagpie.ai's checksum": "更新經此鏡像下載，每個檔案都按 usemagpie.ai 的檢查碼核對",
    "Updates are downloaded from GitHub; a mirror can be used where GitHub is slow": "更新從官方 GitHub 下載；GitHub 慢時可以改用鏡像",
    "The update and its checksum always come from usemagpie.ai; a file from the mirror that doesn't match it is not installed.": "更新資訊和檢查碼始終來自 usemagpie.ai；從鏡像下載的檔案如果與檢查碼不符，magpie 不會安裝它。",
    "Use GitHub": "恢復官方",
