    "Couldn't download {v} through the mirror {mirror}; it may be down or sent a file that doesn't match the release, which isn't installed": "經鏡像 {mirror} 下載 {v} 失敗：鏡像可能不可用，或發來的檔案與釋出版本不符（不會安裝）",
    "Download from GitHub": "改用官方下載",
