    "Puts {dir} first in your user PATH and writes magpie.cmd there, which runs {name}": "把 {dir} 放到你使用者 PATH 的最前面，並在那裡寫一個 magpie.cmd 來執行 {name}",
    "Added: magpie.cmd beside {name} runs it as magpie; open a new PowerShell or Command Prompt window to run magpie": "已新增：{name} 旁邊的 magpie.cmd 會以 magpie 這個命令執行它；新開一個 PowerShell 或命令提示字元視窗即可執行 magpie",
    "which runs {name}": "它執行 {name}",
