    "Added: open a new terminal window to run magpie": "已新增：新開一個終端機視窗即可執行 magpie",
    "macOS runs magpie from a temporary copy until it is moved to Applications: move it there first": "macOS 在 magpie 被移到「應用程式」之前會從臨時副本執行它：請先把它移過去",
