    "In a new terminal, magpie runs this app: {path}": "新終端機裡的 magpie 執行的就是這個 app：{path}",
    "In a new terminal, magpie runs another copy: {path}": "新終端機裡的 magpie 執行的是另一份：{path}",
    "A new terminal can't find the magpie command": "新終端機裡找不到 magpie 命令",
