    "Add to {file}": "新增到 {file}",
    "Adds ~/.local/bin to {file}'s PATH and links magpie there": "把 ~/.local/bin 加進 {file} 的 PATH，並把 magpie 連結到那裡",
    "PowerShell and cmd take up a change in new windows; restart Windows Terminal if it is open": "PowerShell 和 cmd 在新窗口裡生效；Windows Terminal 若已開啟請重啟它",
