    "macOS runs magpie from a temporary copy until it is moved to Applications: move it there, open it again, then add the command": "macOS 在 magpie 被移到「應用程式」之前會從臨時副本執行它：請移過去、重新開啟，再新增命令",
    "magpie is running from its disk image: copy it to Applications, open it from there, then add the command": "magpie 正從磁碟映像執行：請拷到「應用程式」、從那裡開啟，再新增命令",
    "no folder on your PATH can take the magpie command: add ~/.local/bin to a shell's profile below": "PATH 上沒有能放 magpie 命令的資料夾：請在下面把 ~/.local/bin 加進某個 shell 的設定檔",
    "providers, profiles and these settings": "供應商、方案與這些設定",
    "Portable: everything magpie keeps, in the data folder beside it": "便攜模式：magpie 的所有資料都在它旁邊的 data 資料夾裡",
