    "about {amount} a day": "約每天 {amount}",
    "Solid: the balance as magpie read it. Dashed: a straight line fitted through it since the last top-up, carried on to where it runs out. Click to enlarge.": "實線：magpie 讀到的餘額。虛線：從上次充值起用最小二乘擬合的直線，延伸到用完為止。點選可放大。",
    "Latest readings:": "最近的讀數：",
    "Solid: what was left. Dashed: an even pace, full at the cycle's start to empty at its reset; a line above its dashes lasts the cycle, one below runs out before the reset.": "實線：剩餘額度。虛線：勻速用量，週期開始時滿、重置時用完；實線高於虛線則能撐到重置，低於則會在重置前用完。",
    "Each window's line has the dash shown beside its name. Dotted: an even pace, full at the cycle's start to empty at its reset; a line above its dots lasts the cycle, one below runs out before the reset.": "每個時段的線型顯示在它的名稱旁。點線：勻速用量，週期開始時滿、重置時用完；線高於其點線則能撐到重置，低於則會在重置前用完。",
