    "Strict": "嚴格",
    "A conversation stays with the account or key that answered it and never moves to another, even past its usage cap: when that one is rate limited or out of quota, the error goes to the agent. New conversations are routed as usual.": "會話始終留在回答它的帳號或金鑰上，絕不換到別的，即使超過其用量上限也一樣：它被限流或額度用完時，錯誤直接交給智能體。新會話照常路由。",
    "Rate limited": "被限流時",
    "Keeps its place": "保持原位",
    "Goes to the back": "排到最後",
    "Model lists": "模型清單",
    "Wait": "一直等",
    "2 min": "2 分鐘",
    "4 min": "4 分鐘",
    "e.g. 200k": "如 200k",
    "e.g. 5": "如 5",
    "Minutes": "分鐘數",
    "min": "分鐘",
    "slow to start": "遲遲未開始",
    "In magpie": "magpie 內耗時",
    "One rate limited while it still has quota rests as long as the vendor asks, then takes its place in the order again.": "仍有額度卻被限流的帳號按廠商要求休息，之後回到原位繼續使用。",
    "One rate limited (429) while it still has quota goes to the back of the order, behind every one not rate limited since, and comes round again once those ahead of it are rate limited in turn — so the load goes round rather than back to the first each time. Out of quota, it rests as usual. Kept until magpie restarts.": "仍有額度卻被限流（429）的帳號排到最後，位於此後所有未被限流的帳號之後；前面的帳號依次被限流後才再輪到它，負載因此輪轉，而非每次回到第一個。額度用完的照常休息。此順序保留到 magpie 重啟。",
