    "said before, for the same message": "同一條訊息之前已判斷過",
    "in {ms}": "用時 {ms}",
    "Agents never see them: a routing group picks one as its classifier.": "agent 看不到它們：只有路由組把其中一個選作判斷模型。",
    "Jev's names · Fetch models asks the vendor": "Jev 的名字 · 「取得模型」會向廠商取得",
    "Jev endpoint": "Jev 端點",
    "The address Jev is asked at; paste the one from your gateway's docs, e.g. Cloudflare's …/accounts/<account id>/ai/run": "Jev 的請求位址；可直接貼上閘道文件中的位址，例如 Cloudflare 的 …/accounts/<帳戶 ID>/ai/run",
    "Routing groups name its models as {id} for their classifier": "路由組以 {id} 把它的模型選作判斷模型",
    "A decision API on System One (TypeSafe's Jev, a gateway's, or Bailian's decision model) — what a routing group asks as a turn begins": "System One 協議的決策 API（TypeSafe 的 Jev、閘道提供的，或阿里雲百鍊決策模型），路由組在每輪開始時詢問它",
    "a decision API's root, POST …/systemone under it: its models are a routing group's classifier, never an agent's": "決策 API 的根位址，在其下 POST …/systemone：它的模型只作路由組的分類器，不給 Agent 使用",
    "System One endpoint": "System One 端點",
    "Workspace ID": "業務空間 ID",
    "Give the workspace ID your API key belongs to, or pick the Token Plan": "請填寫 API Key 所屬的業務空間 ID，或選擇 Token Plan",
    "e.g. ws-…, from the Bailian console": "例如 ws-…，在百鍊控制台檢視",
    "The workspace your API key belongs to, in the Bailian console; its decision model is asked at that workspace's host": "API Key 所屬的業務空間，在百鍊控制台檢視；決策模型透過該業務空間的域名存取",
    "The address the decision model is asked at, POST …/systemone under it; the workspace ID above fills it in": "決策模型的請求位址，在其下 POST …/systemone；填寫上方的業務空間 ID 即會補全",
    "The address its decision models are asked at, POST …/systemone under it": "該供應商決策模型的請求位址，在其下 POST …/systemone",
    "A decision API is asked with one model: type it and press Detect APIs": "決策 API 一次只問一個模型：填寫模型後點「檢測協議」",
    "Workspace · Beijing": "業務空間 · 北京",
    "Workspace · Singapore": "業務空間 · 新加坡",
    "Token Plan · Beijing": "Token Plan · 北京",
    "as the group's effort says": "按分組的推理強度設定",
    "whatever the agent asks": "無論 Agent 要求什麼",
