    "visual": "視覺",
    "image": "圖片",
    "{model} is asked for OpenAI's fast mode for {agent}, where your provider serves it. Click to send it as {agent} asks": "{agent} 用 {model} 時向你的服務商請求 OpenAI 的快速模式，服務商支援時生效。點選改為依 {agent} 的請求傳送",
    "Ask your provider for OpenAI's fast mode (service_tier \"priority\") on {model} for {agent}: quicker, at a higher price, where it serves it": "{agent} 用 {model} 時向你的服務商請求 OpenAI 的快速模式（service_tier \"priority\"）：服務商支援時更快，價格更高",
    "Routed": "路由到",
    "Effort": "推理強度",
    "Agent's": "按 agent",
    "Levels": "推理檔位",
    "Named": "自定",
    "{n} accounts": "{n} 個帳號",
    "Show 1 more account": "展開其餘 1 個帳號",
    "Show {n} more accounts": "展開其餘 {n} 個帳號",
    "Show fewer accounts": "收起其餘帳號",
    "All {n} accounts": "全部 {n} 個帳號",
    "These accounts' windows together: amounts of one unit are added up; a window said only as a share is the mean of the accounts on one plan, which have the same allowance. Each account is below.": "這些帳號的視窗合起來：同一單位的額度相加；只給出百分比的視窗，取同一方案帳號的平均值（它們的額度相同）。各帳號在下方。",
    "The mean of {n} accounts on one plan": "同一方案 {n} 個帳號的平均值",
    "Unlimited on each of {n} accounts": "{n} 個帳號都不限量",
    "Added up over {n} accounts": "{n} 個帳號相加",
    "{n} more read before it started again: left out": "另有 {n} 個是重設前讀到的，未計入",
    "{n} of them can't spend theirs before a longer window used up starts again: counted as none left": "其中 {n} 個帳號的更長週期已用完、重設前用不上這部分額度，按無剩餘計",
    "The first of them starts again {when}": "最早的一個 {when} 重設",
    "{n} couldn't be read": "{n} 個讀取失敗",
    "An account whose reading failed isn't counted as empty or full: it is left out of these figures": "讀取失敗的帳號不按用完或全滿計算，而是不計入這些數字",
    "Show {n} more keys": "展開其餘 {n} 個金鑰",
