    "{sum} in all": "合計 {sum}",
    "The {n} keys' balances added up": "{n} 個金鑰的餘額之和",
    "Show 1 more account in full": "展開其餘 1 個帳號",
    "Show {n} more accounts in full": "展開其餘 {n} 個帳號",
    "Show the other accounts in brief": "收起其餘帳號",
    "Show all {n} accounts in full": "展開全部 {n} 個帳號",
    "Show every account in brief": "收起全部帳號",
    "Show this account in full": "展開此帳號",
    "Show this account in brief": "收起此帳號",
    "A conversation stays with the account or key that answered it while what the vendor cached of it is worth keeping — within a turn always, across turns while it's fresh.": "廠商快取仍有價值時，會話留在回答過它的帳號或 Key 上：一輪之內始終保持，跨輪則在快取新鮮時保持。",
    "A conversation stays with the account or key that answered it for the whole session, while it can answer.": "會話始終留在回答過它的帳號或 Key 上，只要它仍能回答。",
    "A conversation stays put within a turn, while the agent sends tool results back; when you speak again, routing decides afresh.": "一輪之內（Agent 回傳工具結果時）不換；你再次發言時，路由重新決定。",
    "Every request is routed afresh, whoever answered its conversation before.": "每個請求都重新路由，不論之前由誰回答。",
    "Mask the accounts on every page — email addresses and account names — for a screenshot to share": "給所有頁面的帳號（郵箱位址和帳號名）打碼，方便截圖分享",
    "Least used": "最少使用",
    "requests": "請求",
    "request": "請求",
    "rerouted": "改道",
    "WorkBuddy refuses chats from Codex and Claude Code (their system prompt); use it from Hermes, OpenCode or Pi, or add another provider to this group": "WorkBuddy 會因系統提示詞拒絕 Codex 和 Claude Code 的對話；請在 Hermes、OpenCode 或 Pi 中使用，或在此分組中再加一個供應商",
    "Antigravity answers this 429 to the system prompt of Claude Code and the Claude Agent SDK (Claude Desktop's chats) whatever quota is left, so it is not a quota and waiting won't help; use another provider for these chats, or put one after Antigravity in a routing group": "Antigravity 對 Claude Code 和 Claude Agent SDK（Claude Desktop 的對話）的系統提示詞都會回這個 429，與剩餘額度無關，所以這不是額度用盡，等待也不會好；請用其他供應商處理這些對話，或在路由分組中把另一個供應商排在 Antigravity 之後",
    "Antigravity answers this 429 to Codex's own system prompt for GPT-5 models whatever quota is left, so it is not a quota and waiting won't help; a Codex chat begun on a GPT model keeps that prompt after a model switch or a fork, so start a new chat on this model": "Antigravity 對 Codex 給 GPT-5 模型的系統提示詞都會回這個 429，與剩餘額度無關，所以這不是額度用盡，等待也不會好；在 GPT 模型上開始的 Codex 對話切換模型或分叉後仍帶著這段提示詞，請在這個模型上新開一個對話",
    "Antigravity answers this 429 to Hermes Agent's earlier default persona (its SOUL.md) whatever quota is left, so it is not a quota and waiting won't help; Hermes' current default persona goes through, so put it in SOUL.md, or use another provider for these chats": "Antigravity 對 Hermes Agent 舊版預設人設（SOUL.md）都會回這個 429，與剩餘額度無關，所以這不是額度用盡，等待也不會好；Hermes 目前的預設人設可以通過，請把它寫進 SOUL.md，或為這些對話改用其他供應商",
    "the provider's network firewall blocked requests from this IP; wait a while, or switch to another network or proxy": "供應商的網路防火牆攔截了此 IP 的請求；請稍後再試，或更換網路或代理",
    "ZCode's risk control blocked this account for unusual activity (code 3012); it rests, and the group's other providers are used. If the ZCode app fails on this account too, only ZCode support can lift the block": "ZCode 風控因異常行為封鎖了這個帳號（代碼 3012）；它會暫停使用，改用此分組中的其他供應商。如果用這個帳號在 ZCode 官方 App 裡也失敗，只有 ZCode 客服能解除",
