    "{model} unless the lead names another": "{model}，主代理指定其他模型時除外",
    "The model a subagent starts on when Codex's lead names none; the lead may still name another. To hold every subagent to one model, set the subagent model": "Codex 主代理沒指定模型時子代理用的模型；主代理仍可指定別的。要讓所有子代理固定用一個模型，請設定子代理模型",
    "Claude Code's lead, or a subagent's own definition, may name a model or tier for it; a model set here is for the subagents that name none": "Claude Code 的主代理或子代理自己的定義可以給它指定模型或檔位；這裡設定的模型只用於沒有指定的子代理",
    "{model} unless the lead or the subagent names another": "{model}，主代理或子代理指定其他模型時除外",
