    "its task was sealed by the ChatGPT backend that answered its lead, and only a ChatGPT account can open it": "它的任務由回應主代理的 ChatGPT 後端加密，只有 ChatGPT 帳號能打開",
    "Luna Reserve": "Luna 儲備",
