    "At least: {k} reply read from a session file, which doesn't say when its answer began, so time before that is counted too": "下限：{k} 次讀自會話檔案的回覆。會話檔案不記錄正文何時開始，之前的時間也算在裡面",
    "At least: {k} replies read from session files, which don't say when their answers began, so time before that is counted too": "下限：{k} 次讀自會話檔案的回覆。會話檔案不記錄正文何時開始，之前的時間也算在裡面",
