    "{agent} needs an administrator here, and the administrator prompt was declined.": "{agent} 在這裡需要系統管理員權限，而系統管理員授權提示被拒絕了。",
    "{agent} needs an administrator here, and magpie couldn't ask Windows for one ({why}).": "{agent} 在這裡需要系統管理員權限，而 magpie 無法向 Windows 要求系統管理員權限（{why}）。",
    "Try again and allow it, or run {cmd} in a terminal opened as administrator.": "請再試一次並允許授權，或在以系統管理員身分開啟的終端機中執行 {cmd}。",
