    "Install Claude Code, Codex, Gemini CLI, OpenCode… and the library can give them the same instructions, MCP servers and skills.": "安裝 Claude Code、Codex、Gemini CLI、OpenCode 等之後，資源庫就能給它們同一份指令、MCP 伺服器和技能。",
    "magpie keeps a copy of every file before it writes it.": "magpie 寫入任何檔案前都會先備份一份。",
