    "Drop the list fetched from the vendor; the models.dev one is used until models are fetched again": "丟棄從供應商取得的列表；在重新取得模型前使用 models.dev 的列表",
    "Only through routing groups": "只透過路由分組使用",
    "Searches the web by itself": "自己能聯網搜尋",
    "Both": "兩者都送",
    "Key header": "金鑰標頭",
    "Which header the API key goes in on the Anthropic API. Most services take both; pick one for a service that refuses the two together. magpie also switches to one by itself when a service says so.": "Anthropic API 的 API 金鑰放在哪個標頭裡。多數服務兩個都接受；有的服務不允許兩個同時出現，就選其中一個。服務這樣提示時，magpie 也會自己改成只送一個。",
    "Redaction": "脫敏",
    "Send requests unmasked": "請求不脫敏",
    "Don't check its certificate": "不驗證它的憑證",
    "Set it aside when out of quota or rate limited": "額度用完或被限流時暫停它",
    "Rests": "暫停",
    "Off: a 429 or an out-of-quota refusal doesn't rest its keys, and the next request is sent to it as usual. For a relay whose limits pass in a moment.": "關閉後：429 或額度用完的拒絕不會讓它的金鑰暫停，下一個請求照常送給它。適合限額很快就會恢復的中轉。",
    "Certificate": "憑證",
    "For your own server with a self-signed certificate or one from your company's CA. magpie then can't tell it from another machine answering at its address: turn it on only on a network you trust.": "用於你自己的伺服器，憑證是自簽的或來自公司內部 CA。開啟後 magpie 無法分辨應答的是它本身還是同一位址上的另一台機器：只在你信任的網路中開啟。",
    "Codex compacts on this provider": "Codex 在此服務商上原生壓縮",
    "Codex's compaction is asked of this provider as Codex sent it, and the summary it seals goes back to Codex unchanged. Off, magpie writes the summary. A conversation compacted this way continues only on this provider and account: another is refused with an error, never sent without the context.": "Codex 的壓縮請求原樣交給此服務商，它加密的摘要原樣還給 Codex。關閉時由 magpie 寫摘要。這樣壓縮過的對話只能在此服務商和帳號上繼續：換到別處會報錯說明，絕不丟掉上下文送出。",
    "For a model running on this computer or your local network: secrets, personal data and your masked words go to it as written. Leave it off for a local relay or proxy that passes requests on to a vendor.": "給執行在這臺電腦或區域網裡的模型：金鑰、個人資訊和你設的脫敏詞按原樣發給它。如果它是本地的中轉或代理、會把請求轉給供應商，請保持關閉。",
    "{host} isn't on this computer or your local network: turned on, requests go to it unmasked.": "{host} 不在這臺電腦或區域網裡：開啟後，請求會不脫敏地發給它。",
    "User-Agent": "User-Agent",
    "Send the agent's own User-Agent": "傳送 Agent 自己的 User-Agent",
    "For a plan that serves only the coding agents it names: each request goes with the User-Agent the agent sent (pi, OpenCode, Claude Code…), not magpie's. Requests magpie makes itself, and ones the agent sent without one, still go as magpie. A User-Agent set in Headers above always wins.": "給只允許指定程式設計 Agent 使用的方案：每個請求帶上 Agent 自己送來的 User-Agent（pi、OpenCode、Claude Code…），而不是 magpie 的。magpie 自己發出的請求，以及 Agent 沒帶 User-Agent 的請求，仍以 magpie 的身分傳送。上面請求頭裡設定的 User-Agent 永遠優先。",
    "DeepSeek and GLM models only from their makers' own APIs": "DeepSeek、GLM 模型只走各自官方上游",
    "Upstream": "上游",
    "Cline serves a model from any host its gateway picks; pinned, a request for a DeepSeek model goes only to DeepSeek and one for a GLM model only to Z.ai, which keeps its prompt cache, and fails when that API can't take it": "Cline 的閘道會把一個模型發給它挑的任意上游；釘住後，DeepSeek 模型的請求只發給 DeepSeek 官方，GLM 模型的只發給 Z.ai 官方，快取能命中；官方接不了時請求會失敗，不會換別家",
    "For a relay in front of Anthropic's or OpenAI's own API: Claude Code's WebSearch and Codex's web_search go to it as they were sent, not through magpie's search. magpie doesn't automatically search with it for other models, but you can name it as the searcher.": "用於 Anthropic 或 OpenAI 官方 API 前的中轉：Claude Code 的 WebSearch 和 Codex 的 web_search 原樣發給它，不經 magpie 搜尋。不會自動用它為其他模型搜尋，但可手動選為代搜供應商。",
    "Its models leave the list agents pick from; the routing groups they are in still use them": "它的模型不出現在 Agent 的可選列表裡；所在的路由分組仍會使用它們",
    "Picked: the routing groups it is in use it. Agents don't see it.": "已選：它所在的路由分組會用到。Agent 看不到它。",
    "Left out of {agents}'s model list, on the Agents page": "已在 Agent 頁從 {agents} 的模型列表中隱藏",
    "Kept out of agents' lists by {groups}, a routing group listed alone": "被路由組 {groups} 擋在 Agent 的模型清單外：它的模型清單設為「只列出本組」",
    "The routing group {group} is listed alone, so agents don't see {models}: change its Model lists on the Routing page.": "路由組 {group} 的模型清單設為「只列出本組」，Agent 因此看不到 {models}：在路由頁把它的「模型清單」改成「也列出成員模型」。",
    "{agent}'s model list leaves out {models}: shown again from there, on the Agents page.": "{agent} 的模型列表隱藏了 {models}：要再顯示，請到 Agent 頁的該列表裡開啟。",
    "Agents don't see them: only the routing groups they are in use them.": "Agent 看不到這些模型，只有它們所在的路由分組會用到。",
    "Agents see the models picked.": "Agent 看到的是已勾選的模型。",
    "In no routing group, so no agent can use them now: {models}.": "不在任何路由分組中，暫無 Agent 能用：{models}。",
    "Once saved, make a group of them in Routing.": "儲存後可在「路由」裡為它們建分組。",
    "Make a routing group of {model}": "用 {model} 建路由分組",
    "Make a routing group of it": "用它建路由分組",
    "Pick {group}": "選 {group}",
    "{provider} is used only through routing groups: agents reach {model} by picking {group}.": "{provider} 設為只透過路由分組使用：選 {group} 即可用到 {model}。",
    "{provider} is used only through routing groups, and {model} is in none, so no agent can use it. Make a group of it, or untick “Only through routing groups” in {provider}'s models.": "{provider} 設為只透過路由分組使用，而 {model} 不在任何分組中，沒有 Agent 能用它。可為它建分組，或在 {provider} 的模型中取消勾選「只透過路由分組使用」。",
    "None selected: no agent or routing group uses its models. Its balance and usage still show. Click a model to pick it.": "全不選：Agent 和路由分組都不使用它的模型，餘額和用量照常顯示。點選模型可勾選。",
    "Routing groups use it: none are picked, so the vendor's list is used": "路由分組會用到它：沒有勾選任何模型時，用的是供應商的列表",
    "Click to pick just this model": "點選只選這個模型",
    "Agents see it: none are picked, so the vendor's list is used": "Agent 能看到它：沒有勾選任何模型時，用的是供應商的列表",
    "Bring in": "匯入",
    "Bring in all": "全部匯入",
