    "Vendor's list": "供應商列表",
    "Picked only": "僅所選",
    "Serve the vendor's list, up to {n} of it (dashed), models it lists later too": "提供供應商的列表，最多 {n} 個（虛線框），之後新上的模型也包括在內",
    "Serve only the models picked": "只提供勾選的模型",
    "Usage only": "僅看用量",
    "Best in family": "每系最新",
    "Best in family: agents see the newest model of each family it lists (dashed), up to {n}. A newer one it lists later takes the old one's place.": "每系最新：Agent 看到它列表裡每個系列最新的模型（虛線框），最多 {n} 個。之後上了更新的，會自動取代舊的。",
    "Route nothing to it: no agent or routing group uses its models, and those it lists later aren't added. Its balance and usage still show.": "不往它路由：Agent 和路由分組都不使用它的模型，之後新上的模型也不會加進來。餘額和用量照常顯示。",
    "usage only": "僅看用量",
    "Vendor's list: agents don't see it, the routing groups its models are in use up to {n} of it (dashed). Click a model to pick just it.": "供應商列表：Agent 看不到，模型所在的路由分組最多使用其中 {n} 個（虛線框）。點選模型可單選。",
    "Vendor's list: agents see up to {n} of its models (dashed), and those it lists later. Click a model to pick just it.": "供應商列表：Agent 看到最多 {n} 個模型（虛線框），之後新上的也會看到。點選模型可單選。",
    "Free only": "只選免費",
    "Pick only the free models (those the filter shows), unpicking the others": "只選中免費模型（有篩選時只選篩出來的），其餘取消選中",
    "Working only": "只選可用",
    "Unpicked 1 model that didn't answer": "已取消選取 1 個沒有回應的模型",
    "Unpicked {n} models that didn't answer": "已取消選取 {n} 個沒有回應的模型",
    "Unpick the models whose last test failed; those that answered, and those not tested, stay picked": "取消選取上次測試失敗的模型；測試通過的和未測試的保持選取",
    "Every picked model that was tested answered": "已測試的選取模型都有回應",
