    "repositories their authors tagged {topic} — nobody has reviewed them; read the code before you install one": "作者自己打了 {topic} 標籤的倉庫，未經審閱，安裝前請先看程式碼",
    "Stars": "Star",
    "Unofficial: {owner} tagged it {topic} on GitHub, and nobody at magpie has reviewed it. It is installed from the repository as it stands, and runs with your sign-in or your requests.": "非官方外掛：{owner} 在 GitHub 上給它打了 {topic} 標籤，magpie 沒有審閱過。安裝的是倉庫目前的程式碼，它會用到你的登入資訊或經手你的請求。",
    "Unofficial: {owner} tagged it {topic} on GitHub, and nobody at magpie has reviewed it. It is installed from npm, as its author published it from the repository, and runs with your sign-in or your requests.": "非官方外掛：{owner} 在 GitHub 上給它打了 {topic} 標籤，magpie 沒有審閱過。安裝的是作者從這個倉庫釋出到 npm 的版本，它會用到你的登入資訊或經手你的請求。",
