    "Inside a window a call costs the official price times its rate, on top of the price rate; outside every window the price rate alone counts. The first window that holds a call wins. Times are on the clock of the computer magpie runs on, and 22:00–6:00 crosses midnight. No day ticked is every day. A price you set for a model is scaled by the window too. Changing the windows prices the calls already counted again, as a changed price rate does.": "時段內的呼叫以官方價乘上該時段的倍率計費，疊加在價格倍率之上；時段之外只按價格倍率。呼叫命中第一個符合的時段。時間按執行 magpie 的那台電腦的時鐘，22:00–6:00 表示跨午夜。不勾任何星期表示每天。為模型單獨設的價格同樣按該倍率縮放。修改時段後，已記錄的呼叫也依新時段重新計算，與修改價格倍率相同。",
    "DeepSeek's own API, Command Code, OpenCode Go and Ollama Cloud already count their DeepSeek models' peak hours at double: don't add those hours as a window, or they count twice.": "DeepSeek 官方 API、Command Code、OpenCode Go 和 Ollama Cloud 的 DeepSeek 模型已按各自的尖峰時段雙倍計價：不要再把這些時段設為時段倍率，否則會重複計算。",
